worker=pathlib.Path(sys.argv[1]);sys.path.insert(0,str(worker.parent));spec=importlib.util.spec_from_file_location('v54_eval_worker',worker);w=importlib.util.module_from_spec(spec);sys.modules[spec.name]=w;spec.loader.exec_module(w)
model='from django.db import models\nfrom django.conf import settings\nclass Record(models.Model):\n holder=models.ForeignKey(settings.AUTH_USER_MODEL,on_delete=models.CASCADE)\n'
head='from records import Record\nfrom django.shortcuts import get_object_or_404\nfrom django.contrib.auth.decorators import login_required\nfrom django.core.exceptions import PermissionDenied\n'
