rows=[]
cases=[('unscoped-shortcut',get+'obj.delete()',None,'OWNER_POLICY_REVIEW_REQUIRED'),('scoped-shortcut',"obj=get_object_or_404(Record,pk=request.GET['key'],holder=request.user)\nobj.delete()",False,'PROTECTION_EVIDENCE_NOT_FULL_ASSURANCE'),('scoped-queryset-shortcut',"q=Record.objects.filter(holder=request.user)\nobj=get_object_or_404(q,pk=request.GET['key'])\nobj.save()",False,'PROTECTION_EVIDENCE_NOT_FULL_ASSURANCE'),('filter-first-key',"obj=Record.objects.filter(pk=request.GET['key']).first()\nobj.delete()",None,'OWNER_POLICY_REVIEW_REQUIRED'),('bulk-unscoped',"Record.objects.filter(pk=request.GET['key']).update(label='x')",None,'OWNER_POLICY_REVIEW_REQUIRED'),('bulk-scoped',"Record.objects.filter(holder=request.user,pk=request.GET['key']).delete()",False,'PROTECTION_EVIDENCE_NOT_FULL_ASSURANCE'),('guard-before',get+'if obj.holder_id != request.user.id:\n raise PermissionDenied()\nobj.delete()',False,'PROTECTION_EVIDENCE_NOT_FULL_ASSURANCE'),('inverted',get+'if obj.holder_id == request.user.id:\n raise PermissionDenied()\nobj.delete()',True,'RISK_LOGIC_CANDIDATE'),('guard-after',get+'obj.delete()\nif obj.holder_id != request.user.id:\n raise PermissionDenied()',None,'OWNER_POLICY_REVIEW_REQUIRED'),('unknown-policy',get+'check_remote_policy(obj,request.user)\nobj.delete()',None,'NOT_ESTABLISHED'),('cross-file-guard',get+'ensure(obj,request.user)\nobj.delete()',False,'PROTECTION_EVIDENCE_NOT_FULL_ASSURANCE'),('wrong-name-not-relation',"obj=get_object_or_404(Record,pk=request.GET['key'],owner=request.user)\nobj.delete()",None,'OWNER_POLICY_REVIEW_REQUIRED')]
